    [0, 2],
    [0, 1, 3],
    [1, 2],
    [1],
  ];

  List<int> topologicalSort(List<List<int>> graph) {
    List<int> sorted = [];
    if (graph.isEmpty || graph[0].isEmpty) return sorted;

    int numVertices = graph.length;
    List<int> outdegrees = List.filled(numVertices, 0);
    List<List<int>> reverse = List.generate(numVertices, (_) => []);

    for (int v = 0; v < numVertices; v++) {
      for (int u = 0; u < graph[v].length; u++) {
        outdegrees[u]++;
        reverse[u].add(v);
      }
    }

    List<int> queue = [];
    for (int v = 0; v < numVertices; v++) {
      if (outdegrees[v] == 0) {
        queue.add(v);
      }
    }

    while (queue.isNotEmpty) {
      int v = queue.removeAt(0);
      sorted.add(v);

      for (int u = 0; u < graph[v].length; u++) {
        outdegrees[u]--;
        if (outdegrees[u] == 0) {
          queue.add(u);
        }
      }
    }

    return sorted;
  }

  List<int> topologicalSortResult = topologicalSort(graph);
  print('Topological Sort: ${topologicalSortResult.join(' -> ')}');
}

