bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

List<String> wordBreakAll(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<List<String>> segmentations = [];
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        List<String> prefix = wordBreakAll(s.substring(j + 1, i), wordDict);
        for (String seg in prefix) {
          segmentations.add(s.substring(j + 1, i) + '-' + seg);
        }
      }
    }
  }
  return segmentations;
}

