List<String> wordBreakAll(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<String> results = [];

  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  void backtrack(int idx, List<String> current) {
    if (idx == s.length) {
      results.add(current.join(' '));
      return;
    }

    for (int j = idx; j < s.length; j++) {
      if (dp[j] && wordSet.contains(s.substring(idx, j + 1))) {
        current.add(s.substring(idx, j + 1));
        backtrack(j + 1, current);
        current.removeLast();
      }
    }
  }

  for (int i = 0; i <= s.length; i++) {
    if (dp[i]) {
      backtrack(i, []);
    }
  }

  return results;
}

