enum Role { user, admin, editor, viewer, manager, developer, unknown }

class Permission {
  final String name;
  final String description;

  Permission._internal(this.name, this.description);

  factory Permission(String name) {
    final map = {
      'user': Permission._internal('user', 'basic user permissions'),
      'admin': Permission._internal('admin', 'full administrative permissions'),
      'editor': Permission._internal('editor', 'editing permissions'),
      'viewer': Permission._internal('viewer', 'viewing permissions'),
      'manager': Permission._internal('manager', 'managing permissions'),
      'developer': Permission._internal('developer', 'development permissions'),
      'none': Permission._internal('none', 'no permissions granted'),
    };
    return map[name] ?? Permission._internal('unknown', 'unknown permission');
  }

  bool can(Role role) => role == Role.admin || (role == Role.editor && name != 'editor') || (role == Role.user && name != 'user');

  @override
  String toString() => description;
}

