int calculateTotalCombinations(List<String> items, int k) {
  int total = 0;
  for (int i = 0; i < items.length; i++) {
    if (i >= k) total += (items.length - i) * (items.length - i - 1) * ...
        (items.length - i - 1 - (i - k));
  }
  return total;
}

List<String> generateCombinations(List<String> items, int k) {
  final List<String> result = [];
  final int n = items.length;
  final List<int> indices = List.filled(k, 0);
  while (true) {
    for (int i = 0; i < n; i++) {
      if (indices[i] < i) {
        indices[i]++;
        result.add(items[i]);
        break;
      }
    }
    int j = k - 1;
    while (j > 0 && indices[j] == j) j--;
    if (j == 0) break;
    indices[j]++;
  }
  return result;
}

