}

int _combinations(int k, int n, List<String> items) {
  if (k <= 0 || k > n) return 0;

  if (k == 1) return n;

  int combinations = 0;

  for (int i = 0; i <= n - k; i++) {
    bool valid = true;
    for (int j = 0; j < k; j++) {
      if (items[i + j] == items[i + j + k]) {
        valid = false;
        break;
      }
    }
    if (valid) combinations++;
  }

  return combinations;
}

