bool isSafe(List<List<int>> board, int row, int col) {

  for (int i = 0; i < row; i++) {
    int c = board[i][col];
    if (c == 1) return false; 
  }

  for (int i = row - 1; i >= 0; i--) {
    for (int j = col - 1; j >= 0; j--) {
      int c = board[i][j];
      if (c == 1) return false; 
    }
  }

  for (int i = row - 1; i >= 0; i--) {
    for (int j = col + 1; j < n; j++) {
      int c = board[i][j];
      if (c == 1) return false; 
    }
  }

  return true;
}

