bool isSafe(int row, int col, List<String> board) {
  for (int r = 0; r < row; r++) {
    if (board[r][col] == 'Q') return false;
  }

  for (int c = 0; c < col; c++) {
    if (board[row][c] == 'Q') return false;
  }

  int dr = row - 1;
  int dc = col - 1;
  while (dr >= 0 && dc >= 0) {
    if (board[dr][dc] == 'Q') return false;
    dr--;
    dc--;
  }

  dr = row - 1;
  dc = col + 1;
  while (dr >= 0 && dc < n) {
    if (board[dr][dc] == 'Q') return false;
    dr--;
    dc++;
  }

  return true;
}

