import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  int n;
  if (args.isNotEmpty) {
    n = int.parse(args[0]);
  } else {
    n = 8;
  }

  if (n <= 0) {
    print('N must be a positive integer.');
    return;
  }

  const int totalSolutions = 1 << n; 
  const int maxIterations = 1 << 20; 

  int current = 0;
  int solutionCount = 0;

  String printBoard(int board) {
    const int bitsPerCell = 8;
    String rows = '';
    for (int i = 0; i < n; i++) {
      String row = '';
      for (int j = 0; j < n; j++) {
        if (((board & ((1 << j) << (i * bitsPerCell))) >> (i * bitsPerCell)) & 1 == 1) {
          row += 'Q ';
        } else {
          row += '. ';
        }
      }
      rows += row + '\n';
    }
    return rows;
  }

  bool isSafe(int board, int col) {
    for (int i = 0; i < col; i++) {
      int queenPos = ((board & ((1 << i) << (col * bitsPerCell))) >> (i * bitsPerCell)) & 1;
      if (queenPos == 1) {
        return false;
      }
    }
    return true;
  }

  bool placeNext(int board, int col) {
    if (col == n) {
      solutionCount++;
      if (solutionCount == totalSolutions) {
        print('Total solutions: $solutionCount');
        print('Solving N-Queens for N=$n');
        print('==================================');
        print(printBoard(board));
        return true;
      }
      return false;
    }

    for (int i = 0; i < col; i++) {
      if (isSafe(board, i)) {
        if (placeNext(board | (1 << i), col + 1)) {
          return true;
        }

        board ^= (1 << i);
      }
    }

    return false;
  }

  print('Solving N-Queens for N=$n');
  print('==================================');

  while (current < maxIterations) {
    int temp = current;
    current = (current + 1) & maxIterations;
    if (temp == current) {
      break;
    }

    if (placeNext(0, 0)) {
      break;
    }
  }

  if (current == maxIterations) {
    print('Invalid input: $n');
  } else {
    print('Total solutions: $solutionCount');
  }
}

