  const UNIT_Y = Quaternion(0, 1, 0, 0);

  const UNIT_X = Quaternion(0, 0, 0, 1);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  double conjugate() {
    return x * x - y * y - z * z - w * w;
  }

  double normSquared() {
    return norm() * norm();
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double xx = x * other.x;
    double xy = x * other.y;
    double xz = x * other.z;
    double xw = x * other.w;
    double yy = y * other.y;
    double yz = y * other.z;
    double yw = y * other.w;
    double zz = z * other.z;
    double zw = z * other.w;
    return Quaternion(xx - yy - zz + zw, xy + yw + zz, xz + yz + ww, xx + yy - zz - zw);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    double r = 1 / n;
    return Quaternion(x * r, y * r, z * r, w * r);
  }

  Quaternion normalized() {
    if (norm() == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    double n = norm();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  void rotateAxis(double angle, Quaternion axis) {
    if (axis.norm() == 0) {
      throw ArgumentError('Cannot rotate around zero axis');
    }
    double halfAngle = angle / 2;
    double sinAngle = sin(halfAngle);
    double cosAngle = cos(halfAngle);
    double normAxis = axis.norm();
    double axisX = axis.x / normAxis;
    double axisY = axis.y / normAxis;
    double axisZ = axis.z / normAxis;
    double ax = x * cosAngle + z * sinAngle;
    double az = x * sinAngle - z * cosAngle;
    double ax2 = ax * ax;
    double az2 = az * az;
    return Quaternion(ax2 * cosAngle + az2 * sinAngle,
        ax * sinAngle * cosAngle + az * cosAngle * sinAngle,
        ax * sinAngle * sinAngle - az * cosAngle * cosAngle,
        w * cosAngle);
  }

  void rotateByAngle(double angle) {
    Quaternion axis = UNIT_Z;
    rotateAxis(angle, axis);
  }
}

