    return const Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  const Quaternion subtract(const Quaternion other) {
    return const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  const Quaternion multiply(const Quaternion other) {
    final q3 = x * other.w + y * other.z + z * other.y + w * other.x;
    final q4 = x * other.w + y * other.z + z * other.y + w * other.x;
    return const Quaternion(q3, q4, q3, q4);
  }

  const Quaternion rotateZ(double angle) {
    final cos = cos(angle / 2.0);
    final sin = sin(angle / 2.0);
    return const Quaternion(x * cos - z * sin, y * cos + z * sin, z * cos + x * sin, w * cos);
  }

  const Quaternion rotateY(double angle) {
    final cos = cos(angle / 2.0);
    final sin = sin(angle / 2.0);
    return const Quaternion(x * cos + y * sin, y * cos - x * sin, z * cos + w * sin, w * cos);
  }

  const Quaternion rotateX(double angle) {
    final cos = cos(angle / 2.0);
    final sin = sin(angle / 2.0);
    return const Quaternion(x * cos - y * sin, y * cos + x * sin, z * cos + w * sin, w * cos);
  }

  const Quaternion rotateAxis(
      double ax, double ay, double az, double angle) {
    final cos = cos(angle / 2.0);
    final sin = sin(angle / 2.0);
    return const Quaternion(ax * sin, ay * sin, az * sin, cos);
  }

  const Quaternion rotateAroundZ(double angle) {
    return rotateZ(angle);
  }

  const Quaternion rotateAroundY(double angle) {
    return rotateY(angle);
  }

  const Quaternion rotateAroundX(double angle) {
    return rotateX(angle);
  }

  const Quaternion rotateAxisAroundZ(
      double ax, double ay, double az, double angle) {
    return rotateAxis(ax, ay, az, angle);
  }

  const Quaternion rotateAxisAroundY(
      double ax, double ay, double az, double angle) {
    return rotateAxis(ax, ay, az, angle);
  }

  const Quaternion rotateAxisAroundX(
      double ax, double ay, double az, double angle) {
    return rotateAxis(ax, ay, az, angle);
  }

  const Quaternion rotate(
      double ax, double ay, double az, double angle) {
    return rotateAxisAroundZ(ax, ay, az, angle);
  }

  const Quaternion pow(int exponent) {
    double exponentVal = exponent;
    const Quaternion result = Quaternion.unit();
    while (exponentVal > 0) {
      if (exponentVal & 1 == 1) {
        result *= this;
      }
      this *= this;
      exponentVal >>= 1;
    }
    return result;
  }
}

