  );

  const Quaternion normalized => {
    final n = norm;
    return x * x / n + y * y / n + z * z / n + w * w / n;
  }

  const Quaternion rotate(double angle) {
    final s = sin(angle);
    final c = cos(angle);
    return Quaternion(
      x * c + y * s * 1i,
      y * c + z * s * 2i,
      z * c + w * s * 3i,
      w * c + x * s * 4i,
    );
  }

  const Quaternion operator +(other) => Quaternion(
    x + other.x,
    y + other.y,
    z + other.z,
    w + other.w,
  );

  const Quaternion operator -(other) => Quaternion(
    x - other.x,
    y - other.y,
    z - other.z,
    w - other.w,
  );

  const Quaternion operator *(other) =>
      Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * other.z - y * other.w + z * other.x + w * other.y,
        x * other.w + y * other.z - z * other.x + w * other.y,
      );

  @override
  String toString() {
    final parts = <String>[];
    if (x.abs() >= 1) {
      parts.add(x.toString());
    } else if (y.abs() >= 1) {
      parts.add(y.toString());
    } else if (z.abs() >= 1) {
      parts.add(z.toString());
    } else {
      parts.add(w.toString());
    }
    if (parts.length > 1) {
      parts.add(' ');
