class Quaternion {
  double x = 0.0, y = 0.0, z = 0.0, w = 0.0;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.unit(double angle) {
    w = 1.0;
    x = 0.5 * angle * 2;
    y = 0.5 * angle * 2;
    z = 0.5 * angle * 2;
  }

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.forward(double angle) {
    w = 1.0;
    x = angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.backward(double angle) {
    w = 1.0;
    x = -angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.up(double angle) {
    w = 1.0;
    x = 0.0;
    y = angle;
    z = 0.0;
  }

  Quaternion.down(double angle) {
    w = 1.0;
    x = 0.0;
    y = -angle;
    z = 0.0;
  }

  Quaternion.right(double angle) {
    w = 1.0;
    x = 0.0;
    y = 0.0;
    z = angle;
  }

  Quaternion.left(double angle) {
    w = 1.0;
    x = 0.0;
    y = 0.0;
    z = -angle;
  }

  Quaternion.aroundZ(double angle) {
    w = 1.0;
    x = x * 0.5 * angle * 2;
    y = y * 0.5 * angle * 2;
    z = z * 0.5 * angle * 2;
  }

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0.0) {
      throw ArgumentError("Cannot normalize zero quaternion");
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    return Quaternion(x, y, z, 1.0 / w);
  }

  double magnitude() {
    return (x * x + y * y + z * z + w * w) ** 0.5;
  }

  double dot(Quaternion other) {
    return x * other.x + y * other.y + z * other.z + w * other.w;
  }

  double cross(Quaternion other) {
    return x * other.y * z - y * other.z * x + z * other.x * y;
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    return Quaternion(
      (x * other.w) + (other.x * w),
      (y * other.w) + (other.y * w),
      (z * other.w) + (other.z * w),
      w * other.w - dot(other),
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
