Map<String, int> fn0(List<int> departures, int maxDelay) {
  if (departures.isEmpty) return {};
  int n = departures.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int best = 0;
    for (int j = 0; j < i; j++) {
      int gap = departures[i - 1] - departures[j];
      if (gap <= maxDelay) {
        best = best > dp[j] + 1 ? best : dp[j] + 1;
      }
    }
    dp[i] = best;
  }
  Map<String, int> counts = {};
  for (int i = 1; i <= n; i++) {
    String key = '$i:${dp[i]}';
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

