Map<String, int> fn0(List<int> packetSizes, int mtu) {
  if (packetSizes.isEmpty) {
    return {"*": -1};
  }
  int n = packetSizes.length;
  List<int> dp = List.filled(n + 1, 0);
  Map<String, int> result = {};
  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1];
    if (i >= 4) {
      dp[i] = dp[i] < dp[i - 4] + packetSizes[i - 1] ? dp[i] : dp[i - 4] + packetSizes[i - 1];
    }
    String key = "dp" + i.toString();
    result[key] = dp[i];
  }
  int max = -1;
  for (String key in result.keys) {
    if (result[key] > max) {
      max = result[key];
    }
  }
  String best = "*";
  if (max > 0) {
    for (String key in result.keys) {
      if (result[key] == max) {
        best = key;
        break;
      }
    }
  }
  return {"*": -1, best: max};
}

