@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> events) {
  List<String> stack = [];
  List<String> result = [];
  int net = 0;
  for (String event in events) {
    if (event == 'OPEN') {
      stack.add('D:');
    } else if (event == 'CLOSE') {
      if (stack.isNotEmpty) {
        String top = stack.removeLast();
        if (top == 'D:') net += 1;
        else if (top == 'C:') net -= 1;
      }
    } else if (event.startsWith('D:')) {
      stack.add(event);
    } else if (event.startsWith('C:')) {
      if (stack.isNotEmpty) stack.add(event.substring(1));
    } else if (event == 'FINAL:') {
      for (String stackItem in stack) {
        if (stackItem == 'D:') net += 1;
        else if (stackItem == 'C:') net -= 1;
      }
      result.add('OPEN:$net,result=${net > 0 ? "OPEN" : "CLOSE"}');
    }
  }
