    while (i < n) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = pattern[len - 1];
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1].length;
        } else {
          lps[i] = "";
          i++;
        }
      }
    }
    return lps;
  }

