        matches++;
        textIndex += m;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          textIndex++;
        }
      }
    }

    print('Pattern: $pattern');
    print('Text: $text');
    print('Pattern length: $m');
    print('Text length: $n');
