int bytesToValue(List<int> bytes) {
  int swapBytes(int value, int index) {
    int temp = 0;
    if (index == 0 || index == 2) {
      temp = value & 0xFFFFFFFF;
    } else if (index == 1) {
      temp = (value >> 8) & 0xFFFFFFFF;
    } else {
      temp = (value >> 16) & 0xFFFFFFFF;
    }
    return (temp << (index * 2)) | (temp >> (2 + index));
  }

  int value = 0;
  int temp = 0;

  for (int i = 0; i < bytes.length; i++) {
    int by = bytes[i];
    int swap = swapBytes(by, i);
    if (i * 2 == bytes.length - 1) {
      value = swap;
    } else {
      temp = swap;
    }
  }

  return temp;
}

List<int> valueToBytes(int value) {
  List<int> bytes = [];
  int temp = value;
  int size = temp.length;
  for (int i = 0; i < size; i++) {
    bytes.add(temp & 0xFFFFFFFF);
    temp >>= 32;
  }
  return bytes;
}

List<int> floatToBytes(double value) {
  int swapBytes(int value, int index) {
    int temp = 0;
    if (index == 0 || index == 2) {
      temp = value & 0xFFFFFFFF;
    } else if (index == 1) {
      temp = (value >> 8) & 0xFFFFFFFF;
    } else {
      temp = (value >> 16) & 0xFFFFFFFF;
    }
    return (temp << (index * 2)) | (temp >> (2 + index));
  }

  double f = value;
  int sign = f < 0 ? 1 : 0;
  f = f < 0 ? -f : f;

  int exp = 0;
  int frac = 0;

  if (f == 0.0) {
    exp = 0;
    frac = 0;
  } else if (f == 0.5) {
    exp = -1;
    frac = 1;
  } else {
    exp = 0;
    frac = f * 2;
  }

  int temp = sign;
  if (exp < 0) {
    temp |= 0x80000000;
    exp = -exp;
  } else if (exp > 30) {
    temp |= 0x40000000;
    exp = 30;
  }

  int exBytes = exp & 0xFFFFFFFF;
  int frBytes = frac & 0xFFFFFFFF;

  List<int> bytes = [exBytes, frBytes];
  for (int i = 0; i < bytes.length; i++) {
    bytes[i] = swapBytes(bytes[i], i);
  }
  return bytes;
}

int hostToNetwork(int value) {
  int temp = value & 0xFFFFFFFF;
  int little = 0;
  for (int i = 0; i < 4; i++) {
    little = ((little << 2) | (temp & 3)) & 0xFFFFFFFF;
    temp >>= 2;
  }
  return little;
}

List<int> hostToNetworkArray(List<int> values) {
  List<int> network = [];
  for (int value in values) {
    network.add(hostToNetwork(value));
  }
  return network;
}

int networkToHost(int value) {
  int temp = value & 0xFFFFFFFF;
  int big = 0;
  for (int i = 0; i < 4; i++) {
    big = ((big << 2) | (temp & 3)) & 0xFFFFFFFF;
    temp >>= 2;
  }
  return big;
}

List<int> networkToHostArray(List<int> values) {
  List<int> host = [];
  for (int value in values) {
    host.add(networkToHost(value));
  }
  return host;
}

