  for (int item in transactionSet) {
    itemToTransactions[item] = {};
  }

  for (int i = 0; i < transactionSet.length; i++) {
    for (int j = i + 1; j < transactionSet.length; j++) {
      if (transactionSet.contains(i) && transactionSet.contains(j)) {
        itemToTransactions[i]!.add(j);
        itemToTransactions[j]!.add(i);
      }
    }
  }

  Map<int, Map<int, int>> supportCount = {};

  for (int item in transactionSet) {
    if (itemToTransactions[item]!.isEmpty) continue;
    int transactions = itemToTransactions[item]!.length;
    supportCount[transactions] = (supportCount[transactions] ?? {})..addAll(itemToTransactions[item]!);
  }

  Map<int, Set<int>> frequentItemsets = {};
  int k = 1;

  while (supportCount.isNotEmpty) {
    Map<int, Map<int, int>> nextSupport = {};
    for (int s in supportCount.keys) {
      for (int item in supportCount[s]!.keys) {
        int confidence = supportCount[s]![item]! / transactions;
        if (confidence >= minConfidence) {
          nextSupport[s] = (nextSupport[s] ?? {})..add(item);
        }
      }
    }

    frequentItemsets[k] = nextSupport.isEmpty ? {} : nextSupport.keys.toList();
    supportCount = nextSupport;
    k++;
  }

  print('Frequent Itemsets:');
  for (int k = 1; k <= frequentItemsets.length; k++) {
    print('F${k}: ${frequentItemsets[k]!.join(', ')} (support: ${supportCount[k]! / transactionSet.length}, confidence: ${supportCount[k]! / transactions})');
  }

  Map<int, Map<int, int>> allRules = {};
  Set<int> currentItems = frequentItemsets[1]!;

  while (currentItems.isNotEmpty) {
    int item = currentItems.removeLast();
    Set<int> candidate = {};

    for (int i = 0; i < frequentItemsets.length; i++) {
      if (frequentItemsets[i]!.contains(item)) {
        candidate.addAll(frequentItemsets[i]!);
      }
    }

    if (candidate.length >= 2) {
      Map<int, int> freq = {};
      for (int item2 in candidate) {
        freq[item2] = (freq[item2] ?? 0) + 1;
      }
      int minFreq = 0;
      bool largeFrequent = true;

      for (int item2 in freq.keys) {
        if (freq[item2]! < minFreq) {
          minFreq = freq[item2]!;
        }
      }

      if (minFreq >= minSupport) {
        allRules[item] = (allRules[item] ?? {})..addAll(freq);
      }
    }
  }

  print('\nAssociation Rules:');
  for (int item in allRules.keys) {
    List<int> items = allRules[item]!.keys.toList();
    items.sort();
    print('$item -> ${items.join(', ')} (support: ${allRules[item]! / transactionSet.length}, confidence: ${allRules[item]! / transactions})');
