      if (found) {
        Set<int> suppItems = {};
        for (var item in is) {
          suppItems.add(item);
        }
        for (var item in other) {
          if (!suppItems.contains(item)) {
            suppItems.add(item);
          }
        }

        Set<int> confItems = {};
        for (var item in is) {
          confItems.add(item);
        }
        for (var item in other) {
          if (!confItems.contains(item)) {
            confItems.add(item);
          }
        }

        assocRules[is] = [confItems, suppItems];
      }
    }
  }

  print('\nAssociation Rules:');
  for (var is in frequentItemsets) {
    List<int> items = is.toList()..sort();

    Set<int> confItems = {};
    for (var item in is) {
      confItems.add(item);
    }

    List<String> confStr = confItems.map((item) => item == 0 ? 'Milk' : item == 1 ? 'Bread' : 'Butter').toList();

    List<String> suppStr = frequentItemsets.map((item) => item == 0 ? 'Milk' : item == 1 ? 'Bread' : 'Butter').toList();

    double conf = support[is]!;

    print('${confStr.join(' -> ')} (support: $conf, confidence: $conf * ${frequentItemsets.length / trans.length})');
  }
