  dp[0] = (readings[0] - referenceLevel).abs();
  for (int i = 1; i < n; i++) {
    dp[i] = (readings[i] - readings[i - 1]).abs() + dp[i - 1];
  }
  List<int> prefix = List.filled(n, 0);
  prefix[0] = dp[0];
  for (int i = 1; i < n; i++) {
    prefix[i] = prefix[i - 1] + dp[i];
  }
  List<int> suffix = List.filled(n, 0);
  suffix[n - 1] = dp[n - 1];
  for (int i = n - 2; i >= 0; i--) {
    suffix[i] = suffix[i + 1] + dp[i];
  }
  List<int> best = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    if (prefix[i] >= suffix[i]) {
      best[i] = prefix[i];
    } else {
      best[i] = suffix[i];
    }
  }
  return best;
}

