Map<String, int> fn0(List<int> dailyDeliveries, int daysPerCycle) {
  final Map<String, int> results = {
    'longestInterval': 0,
    'totalDeficitDays': 0,
    'distinctIntervals': 0,
  };

  if (daysPerCycle <= 0) {
    return results;
  }

  final List<int> cycleStarts = [];
  int cycleIndex = 0;
  int currentDay = 0;

  for (final int delivery in dailyDeliveries) {
    if (delivery <= 0) {
      return results;
