    while (currentDay < delivery) {
      cycleStarts.add(cycleIndex);
      currentDay += daysPerCycle;
      cycleIndex++;
    }

    if (currentDay >= delivery) {
      cycleStarts.add(cycleIndex);
      cycleIndex++;
    }

    while (currentDay > delivery) {
      cycleIndex++;
      currentDay -= daysPerCycle;
    }
  }

  int longestInterval = 0;
  int distinctIntervals = 0;

  for (int i = 1; i < cycleStarts.length; i++) {
    final int gap = cycleStarts[i] - cycleStarts[i - 1];

    if (gap > longestInterval) {
      longestInterval = gap;
    }

    if (gap != longestInterval) {
      distinctIntervals++;
    }
  }

  final int totalDeficitDays = cycleStarts.length - 1;

  results['longestInterval'] = longestInterval;
  results['totalDeficitDays'] = totalDeficitDays;
  results['distinctIntervals'] = distinctIntervals;

  return results;
}

