Map<String, int> fn0(List<int> dailyCounts, int weeklyThreshold) {
  if (dailyCounts.isEmpty) {
    return {
      'longestInterval': 0,
      'totalDeficitDays': 0,
      'distinctIntervals': 0,
    };
  }

  int left = 0;
  int sum = 0;
  int bestStart = 0;
  int bestLen = 0;
  List<int> validEnds = [];

  for (int right = 0; right < dailyCounts.length; right++) {
    sum += dailyCounts[right];

    while (sum > weeklyThreshold) {
      sum -= dailyCounts[left];
      left++;
    }

    int windowLen = right - left + 1;
    validEnds.add(left);

    if (left > 0) {
      for (int end = left - 1; end >= 0; end--) {
        if (validEnds[end] == right) {
          break;
        }
      }
    }

    if (windowLen > bestLen) {
      bestLen = windowLen;
      bestStart = left;
    }
  }

  int longestInterval = bestLen;
  int totalDeficitDays = sum - (longestInterval * weeklyThreshold);
  int distinctIntervals = validEnds.length;

  return {
    'longestInterval': longestInterval,
    'totalDeficitDays': totalDeficitDays,
    'distinctIntervals': distinctIntervals,
  };
}

