  Rectangle union(Rectangle other) =>
      Rectangle(centerX - max(0, (other.centerX - centerX).abs()),
          centerY - max(0, (other.centerY - centerY).abs()),
          width + other.width,
          height + other.height);

  @override
  String toString() => 'Rectangle(center: ($centerX, $centerY), '
          'halfWidth: $width, halfHeight: $height)';
}

