      : this(0, 0, side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x, p2.y);

  Rectangle.origin() : this(0, 0, 1, 1);

  double get left => x1 < x2 ? x1 : x2;
  double get right => x1 < x2 ? x2 : x1;
  double get bottom => y1 < y2 ? y1 : y2;
  double get top => y1 < y2 ? y2 : y1;

  Rectangle union(Rectangle other) {
    return Rectangle(
        left < other.left ? left : other.left,
        bottom < other.bottom ? bottom : other.bottom,
        right > other.right ? right : other.right,
        top > other.top ? top : other.top);
  }

  Rectangle intersect(Rectangle other) {
    if (left > other.right || other.left > right) {
      return Rectangle.origin();
    }
    if (bottom > other.top || other.bottom > top) {
      return Rectangle.origin();
    }
    return Rectangle(other.left, other.bottom, right, top);
  }

  bool contains(Point p) =>
      p.x >= left && p.x <= right && p.y >= bottom && p.y <= top;

  @override
  String toString() => 'Rectangle($x1, $y1, $x2, $y2)';
}

