      : x1 = p1.x < p2.x ? p1.x : p2.x,
        y1 = p1.y < p2.y ? p1.y : p2.y,
        x2 = p1.x > p2.x ? p1.x : p2.x,
        y2 = p1.y > p2.y ? p1.y : p2.y;

  Rectangle.fromPoints2(Point p1, Point p2, double scale)
      : x1 = p1.x < p2.x ? p1.x : p2.x * scale,
        y1 = p1.y < p2.y ? p1.y : p2.y * scale,
        x2 = p1.x > p2.x ? p1.x : p2.x * scale,
        y2 = p1.y > p@2.y ? p1.y : p2.y * scale;

