      : x1 = p1.x < p2.x ? p1.x : p2.x * scaleX,
        y1 = p1.y < p2.y ? p1.y : p2.y * scaleY,
        x2 = p1.x > p2.x ? p1.x : p2.x * scaleX,
        y2 = p1.y > p2.y ? p1.y : p2.y * scaleY;

  Rectangle.fromPoints4(Point p1, Point p2)
