    [4.0, 4.0],
    [2.0, 2.5],
    [3.5, 4.5],
    [1.0, 4.0],
    [2.5, 5.0],
    [4.5, 7.0],
  ];

  final int k = 3;

  final clusters = List.generate(k, (_) => <List<double>>[]);

  double eps = double.infinity;
  int maxIterations = 100;

  double distance(List<double> p1, List<double> p2) {
    double sum = 0;
    for (int i = 0; i < p1.length; i++) {
      sum += pow(p1[i] - p2[i], 2);
    }
    return sqrt(sum);
  }

  bool updateClusters(List<List<double>> points, List<List<double>> clusters) {
    bool changed = false;

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int currentCluster = -1;

      for (int j = 0; j < clusters.length; j++) {
        double dist = distance(points[i], clusters[j]);
        if (dist < minDist) {
          minDist = dist;
          currentCluster = j;
        }
      }

      if (currentCluster != clusters[i][0]) {
        clusters[i][0] = currentCluster;
        changed = true;
      }
    }

    return changed;
  }

  int clusterId(List<double> point) {
    for (int i = 0; i < point.length; i++) {
      if (point[i] != point[0]) {
        return i;
      }
    }
    return 0;
  }

  List<int> clusterLabels(List<List<double>> clusters) {
    List<int> labels = List.filled(clusters.length, 0);

    for (int i = 0; i < clusters.length; i++) {
      labels[i] = clusterId(clusters[i]);
    }

    return labels;
  }

  List<List<double>> centroidMeans = List.generate(
    k,
    (_) => [
      rand.nextDouble() * 10 - 5,
      rand.nextDouble() * 10 - 5,
    ],
  );

  List<List<double>> current = List.from(points);
  List<int> labels = List.filled(current.length, 0);

  int iteration = 0;

  while (eps > 1e-4 && iteration < maxIterations) {
    iteration++;

    bool moved = false;

    for (int i = 0; i < current.length; i++) {
      moved |= updateClusters(current, clusters);

      for (int j = 0; j < k; j++) {
        if (clusters[j].isNotEmpty) {
          centroidMeans[j][0] =
              centroidMeans[j][0] + current[i][0] / clusters[j].length;
          centroidMeans[j][1] =
              centroidMeans[j][1] + current[i][1] / clusters[j].length;
        }
      }
    }

    if (!moved) {
      eps = double.infinity;
      continue;
    }

    labels = clusterLabels(clusters);

    List<List<double>> newCurrent = List.generate(
      current.length,
      (_) => [
        rand.nextDouble() * 10 - 5,
        rand.nextDouble() * 10 - 5,
      ],
    );

    for (int i = 0; i < current.length; i++) {
      int clusterId = labels[i];
      newCurrent[i][0] = centroidMeans[clusterId][0];
      newCurrent[i][1] = centroidMeans[clusterId][1];
    }

    current = newCurrent;

    if (eps == double.infinity) {
      eps = 0;
    } else if (eps > 0) {
      eps = eps / 2;
    }
  }

  print('Converged in $iteration iteration(s).');
  print('Centroid means:');
  for (int i = 0; i < k; i++) {
    print('Cluster $i: (${centroidMeans[i][0]}, ${centroidMeans[i][1]})');
  }

  print('  Points:');
  for (int i = 0; i < current.length; i++) {
    print('Cluster ${labels[i]}: (${current[i][0]}, ${current[i][1]})');
  }
}

