  int iter = 0;
  Set<int> clusterIds = {};

  List<List<int>> centroids = List.generate(k, (_) => points[rand.nextInt(points.length)]);

  List<List<int>> assignments = List.generate(points.length, (_) => List<int>.filled(k, 0));

  bool converged = false;

  while (!converged) {
    bool changed = false;

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int bestCluster = 0;

      for (int c = 0; c < k; c++) {
        int d = (points[i][0] - centroids[c][0]).abs() +
            (points[i][1] - centroids[c][1]).abs();
        if (d < minDist) {
          minDist = d;
          bestCluster = c;
        }
      }

      if (assignments[i][bestCluster] == 0) {
        assignments[i][bestCluster]++;
        changed = true;
      }
    }

    if (!changed) {
      converged = true;
      continue;
    }

    for (int c = 0; c < k; c++) {
      List<int> pointsInCluster = [];
      List<double> center = List.from(centroids[c]);

