bool fn0(String p0) {
  bool isEdge(String c) => c == '.' || c == '#';
  bool isPassable(String c) => c == '.' || c == ' ';
  bool isOpen(String c) => c == 'N' || c == 'E' || c == 'S' || c == 'W';

  List<String> maze = [];
  String line = '';
  for (int i = 0; i < p0.length; i++) {
    if (p0[i] == '\n') {
      if (line.isNotEmpty) maze.add(line);
      line = '';
    } else {
      line += p0[i];
    }
  }
  if (line.isNotEmpty) maze.add(line);

  Set<int> visited = {};
  int width = maze[0].length;
  int height = maze.length;

  void dfs(int r, int c) {
    if (r < 0 || r >= height || c < 0 || c >= width) return;
    if (maze[r][c] != '.' || visited.contains(r * width + c)) return;

    visited.add(r * width + c);
    dfs(r - 1, c);
    dfs(r + 1, c);
    dfs(r, c - 1);
    dfs(r, c + 1);
  }

  for (int r = 0; r < height; r++) {
    for (int c = 0; c < width; c++) {
      if (maze[r][c] == '#' || visited.contains(r * width + c)) continue;
      if (isEdge(maze[r][c])) continue;

      if (isOpen(maze[r - 1][c])) {
        dfs(r - 1, c);
      }
      if (isOpen(maze[r + 1][c])) {
        dfs(r + 1, c);
      }
      if (isOpen(maze[r][c - 1])) {
        dfs(r, c - 1);
      }
      if (isOpen(maze[r][c + 1])) {
        dfs(r, c + 1);
      }

      break;
    }
  }

  for (int r = 0; r < height; r++) {
    for (int c = 0; c < width; c++) {
      if (isPassable(maze[r][c])) continue;
      if (visited.contains(r * width + c)) continue;

      return true;
    }
  }

  return false;
}

